"use client";
import Link from "next/link";
import Image from "@/components/courses/CourseImage";
import { useParams, useRouter, notFound } from "next/navigation";
import { useState, useEffect, type FormEvent } from "react";
import { ArrowLeft, ArrowRight, Award, BookOpen, CheckCircle2, Clock3, Download, GraduationCap, LockKeyhole, Play, Star, Upload, Users } from "lucide-react";
import Artwork from "@/components/ui/Artwork";
import { useLearnova } from "@/components/LearnovaProvider";
import { EmptyState, LoadingCards, ProgressBar, StatusBadge } from "@/components/ui";
import { type Course } from "@/data/courses";
import { assignmentFor, quizFor } from "@/data/learning";
import { api, API_URL, errorMessage } from "@/lib/api";
import type { Question } from "@/data/learning";
